const base=$('Parse Idea JSON').item.json;
const evalStr=$input.item.json.choices?.[0]?.message?.content||'{}';
let ev; try{ ev=JSON.parse(evalStr);}catch(e){ const m=evalStr.match(/\{[\s\S]*\}/); ev=m?JSON.parse(m[0]):{}; }
if(!ev.overall){ const avg=(ev.demand_score+ev.competition_score+ev.value_score+ev.price_score+ev.market_confidence)/5; ev.overall=Math.round(avg*10)/10; }
if(!ev.verdict) ev.verdict=ev.overall>=7?'APPROVED':'REJECTED';
return [{ json: { ...base, evaluation: ev, ...ev } }];

